select id, 'kor', 'text', null, null, jsonb_build_object('kind', 'story', 'slides', jsonb_build_array('Сиқырлы шаршыда әр жолдың қосындысы бірдей болуы керек.', 'Кейде бір жолдағы екі бос ұяшыққа әртүрлі сандар қойса да, қосынды дұрыс шығуы мүмкін — бұл есептің бірнеше шешімі бар дегенді білдіреді.')), 0 from public.topics where title = 'Логикалық және бірнеше шешімі бар есептер' and grade = 3 and track = 'base';

insert into public.lesson_blocks (topic_id, stage, block_type, content, configuration, sort_order)
select id, 'qurastyr', 'number_builder', 'Соңғы жолдың екі бос ұяшығына, қосындысы 15 болатындай кез келген сандарды қой.', jsonb_build_object('kind', 'magic-square', 'cells', jsonb_build_array(4, 9, 2, 3, 5, 7, null, null, 6), 'targetSum', 15), 0 from public.topics where title = 'Логикалық және бірнеше шешімі бар есептер' and grade = 3 and track = 'base';

