insert into public.lesson_blocks (topic_id, stage, block_type, content, configuration, sort_order)
select id, 'qoldan', 'question', 'Кестеде әр жолдың қосындысы 12 болу керек: 5, 3, ?. Жасырын санды тап.', '{}'::jsonb, 0 from public.topics where title = 'Логикалық және бірнеше шешімі бар есептер' and grade = 3 and track = 'base';

insert into public.questions (lesson_block_id, question_text, question_type, correct_answer, explanation, hint, points)
select lb.id, 'Кестеде әр жолдың қосындысы 12 болу керек: 5, 3, ?. Жасырын санды тап.', 'short_answer', '4'::jsonb, '5 + 3 + 4 = 12.', 'Екі белгілі санды қосып, 12-ден азайт.', 1 from public.lesson_blocks lb join public.topics tp on tp.id = lb.topic_id where tp.title = 'Логикалық және бірнеше шешімі бар есептер' and tp.grade = 3 and tp.track = 'base' and lb.stage = 'qoldan';

