insert into public.question_options (question_id, option_text, is_correct, sort_order)
select q.id, opt.text, opt.is_correct, opt.ord from public.questions q join public.lesson_blocks lb on lb.id = q.lesson_block_id join public.topics t2 on t2.id = lb.topic_id cross join (values ('5', true, 0), ('4', false, 1), ('6', false, 2), ('7', false, 3)) as opt(text, is_correct, ord) where t2.title = 'Логикалық және бірнеше шешімі бар есептер' and t2.grade = 3 and t2.track = 'base' and lb.stage = 'bekit' and lb.sort_order = 2;

